package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Prueba de entrega (tabla EVIDENCIA_ENTREGA, RF-M6-06, RN-09). La foto y la firma se guardan como imagen en
 * base64.
 * <p>
 * EN: Delivery proof (EVIDENCIA_ENTREGA table, RF-M6-06, RN-09). The photo and the signature are stored as base64
 * images.
 */
@Entity
@Table(name = "EVIDENCIA_ENTREGA")
public class DeliveryProof {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del servicio. EN: The delivery id. */
    @Column(name = "SERVICIO_ID", nullable = false) private Long deliveryId;
    /** El id del domiciliario. EN: The courier id. */
    @Column(name = "DOMICILIARIO_ID", nullable = false) private Long courierId;
    /** El tipo de prueba. EN: The proof type. */
    @Column(name = "TIPO", nullable = false, length = 10) private ProofType type;
    /** El dato de la prueba: PIN o imagen en base64. EN: The proof data: PIN or base64 image. */
    @Lob @Column(name = "DATO") private String item;
    /** La fecha en minutos de reloj. EN: The date in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA", nullable = false) private Double date;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected DeliveryProof() {}

    /**
     * Crea una prueba de entrega.
     * <p>
     * EN: Creates a delivery proof.
     *
     * @param deliveryId id del servicio / delivery id
     * @param courierId id del domiciliario / courier id
     * @param type PIN, foto o firma / PIN, photo or signature
     * @param item el dato: PIN o imagen en base64 / the data: PIN or base64 image
     * @param date fecha en minutos de reloj / date in clock minutes
     */
    public DeliveryProof(long deliveryId, long courierId, ProofType type, String item, double date) {
        this.deliveryId = deliveryId; this.courierId = courierId; this.type = type; this.item = item; this.date = date;
    }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del servicio.
     * <p>
     * EN: Returns the delivery id.
     *
     * @return el id del servicio / the delivery id
     */
    public Long getDeliveryId() { return deliveryId; }

    /**
     * Devuelve el id del domiciliario.
     * <p>
     * EN: Returns the courier id.
     *
     * @return el id del domiciliario / the courier id
     */
    public Long getCourierId() { return courierId; }

    /**
     * Devuelve el tipo de prueba.
     * <p>
     * EN: Returns the proof type.
     *
     * @return el tipo de prueba / the proof type
     */
    public ProofType getType() { return type; }

    /**
     * Devuelve el dato de la prueba: PIN o imagen en base64.
     * <p>
     * EN: Returns the proof data: PIN or base64 image.
     *
     * @return el dato de la prueba: PIN o imagen en base64 / the proof data: PIN or base64 image
     */
    public String getItem() { return item; }

    /**
     * Devuelve la fecha en minutos de reloj.
     * <p>
     * EN: Returns the date in clock minutes.
     *
     * @return la fecha en minutos de reloj / the date in clock minutes
     */
    public Double getDate() { return date; }
}
